// AVPN: country names for every ISO 3166-1 alpha-2 code the app can receive, in the UI languages that Qt's locale
// data does not cover (QLocale::territoryToString is English only). Generated from the CLDR data of macOS
// (Foundation Locale.localizedString(forRegionCode:)) by:
//   xcrun swift -e 'import Foundation; for r in Locale.Region.isoRegions where r.identifier.count == 2 {
//     let c = r.identifier; print(c, Locale(identifier: "ru").localizedString(forRegionCode: c)!,
//     Locale(identifier: "es").localizedString(forRegionCode: c)!, separator: "\t") }'
// Do not edit by hand: regenerate. The short forms the UI already used («США», «Великобритания»…) stay as overrides
// in DoctorReport.h::countryNameRu / countryNameEs. Pure, header-only.
