// The name of `code` (upper-case alpha-2) in `lang` ("ru" | "es"); "" when the code or the language is unknown.
inline QString name(const QString &code, const QString &lang)
{
    static const QHash<QString, int> index = [] {
        QHash<QString, int> h;
        int n = 0;
        const Entry *t = table(n);
        for (int i = 0; i < n; ++i)
            h.insert(QString::fromLatin1(t[i].code), i);
        return h;
    }();
    const auto it = index.constFind(code);
    if (it == index.constEnd())
        return QString();
    int n = 0;
    const Entry &e = table(n)[it.value()];
    if (lang.startsWith(QLatin1String("ru")))
        return QString::fromUtf8(e.ru);
    if (lang.startsWith(QLatin1String("es")))
        return QString::fromUtf8(e.es);
    return QString();
}

